def call_with_exponential_backoff(target_func, max_retries: int = 3):
    attempts = 0
    base_delay = 0.01
    last_err = None
    while attempts < max_retries:
        attempts += 1
        try:
            return target_func()
        except Exception as e:
            last_err = e
            if attempts < max_retries:
                delay = base_delay * (2 ** (attempts - 1))
                time.sleep(delay)
    raise RuntimeError(f'Exceeded {max_retries} retries: {last_err}')

