def sliding_window_chunker(text: str, chunk_size: int, chunk_overlap: int) -> list[dict]:
    if chunk_overlap >= chunk_size or chunk_overlap < 0:
        raise ValueError('chunk_overlap 必须小于 chunk_size 且大于等于 0')
    step = chunk_size - chunk_overlap
    chunks = []
    idx = 0
    start = 0
    while start < len(text):
        end = min(start + chunk_size, len(text))
        piece = text[start:end]
        if piece:
            chunks.append({
                'index': idx,
                'text': piece,
                'start': start,
                'end': end
            })
            idx += 1
        if end == len(text):
            break
        start += step
    return chunks

def combine_rankings_rrf(ranked_lists: list[list[str]], k: int = 60) -> list[tuple[str, float]]:
    scores = defaultdict(float)
    for r_list in ranked_lists:
        for rank, doc_id in enumerate(r_list, start=1):
            scores[doc_id] += 1.0 / (k + rank)

    sorted_items = sorted(scores.items(), key=lambda x: x[1], reverse=True)
    return [(doc_id, round(score, 5)) for doc_id, score in sorted_items]

