class SimpleRunnablePipeline:
    def __init__(self, functions=None):
        self.functions = list(functions) if functions else []

    def __or__(self, other):
        if isinstance(other, SimpleRunnablePipeline):
            return SimpleRunnablePipeline(self.functions + other.functions)
        elif callable(other):
            return SimpleRunnablePipeline(self.functions + [other])
        else:
            raise TypeError('管道右侧必须为 SimpleRunnablePipeline 或可调用对象')

    def invoke(self, data):
        current = data
        for f in self.functions:
            current = f(current)
        return current

