def compact_synthesizer(query: str, contexts: list[str], max_chars: int) -> str:
    if not contexts:
        return '未检索到相关内容'

    merged_pieces = []
    current_len = 0
    for c in contexts:
        c_clean = c.strip()
        if not c_clean:
            continue
        # 考虑换行符占 1 个字符
        added_len = len(c_clean) + (1 if merged_pieces else 0)
        if current_len + added_len <= max_chars:
            merged_pieces.append(c_clean)
            current_len += added_len
        else:
            # 超出预算停止容纳
            break

    if not merged_pieces:
        merged_context = contexts[0][:max_chars]
    else:
        merged_context = '\n'.join(merged_pieces)

    return f"[参考知识]\n{merged_context}\n\n[用户提问]\n{query}"

