def production_rag_router(question: str, docs: list[dict], min_score: float) -> dict:
    valid_docs = [d for d in docs if d.get('score', 0.0) >= min_score]
    if not valid_docs:
        return {
            'status': 'REFUSED',
            'output': '知识库中未检索到相关内容。',
            'source_ids': []
        }

    # 挑选得分最高的合格文档
    valid_docs.sort(key=lambda x: x.get('score', 0.0), reverse=True)
    top_doc = valid_docs[0]
    source_ids = [d['id'] for d in valid_docs]

    return {
        'status': 'ANSWERED',
        'output': f"根据资料，解答如下：{top_doc['text']} [来源: {top_doc['id']}]",
        'source_ids': source_ids
    }
